// Fusiona los datos guardados de la sesión con los que llegan en el contrato y los valida.
// Solo se aceptan valores válidos; los inválidos se informan y no pisan lo guardado.
const entrada = $('Entrada: Contrato Identificación').first().json;
const registro = $input.first().json || {};
if (registro.error) throw new Error('No se pudo leer la sesión en NocoDB: ' + String(registro.error.message ?? registro.error));
// Registro de la tabla Memoria_Clientes: { id, fields: { Nombre, Apellido, Email, Telefono, Identificado, ... } }
const f = registro.fields || {};
const guardado = { nombre: f.Nombre, apellido: f.Apellido, email: f.Email, telefono: f.Telefono, estado: f.Identificado ? 'IDENTIFICADO' : '' };
const limpiar = (v) => (v === undefined || v === null ? '' : String(v).trim());
const capitalizar = (s) => s.toLowerCase().replace(/(^|[\s'-])(\p{L})/gu, (m, sep, l) => sep + l.toUpperCase());

const CAMPOS = ['nombre', 'apellido', 'email', 'telefono'];
const ETIQUETAS = { nombre: 'nombre', apellido: 'apellido', email: 'correo electrónico', telefono: 'teléfono' };

const actual = Object.fromEntries(CAMPOS.map((c) => [c, limpiar(guardado[c])]));
const nuevos = {};
const invalidos = [];

for (const c of CAMPOS) {
  let v = limpiar(entrada[c]);
  if (!v) continue;
  if (c === 'nombre' || c === 'apellido') {
    v = v.replace(/\s+/g, ' ');
    if (!/^\p{L}[\p{L}\s'.-]{0,59}$/u.test(v)) { invalidos.push({ campo: c, valor: v, motivo: 'solo puede contener letras' }); continue; }
    v = capitalizar(v);
  }
  if (c === 'email') {
    v = v.toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v)) { invalidos.push({ campo: c, valor: v, motivo: 'revisá el formato' }); continue; }
  }
  if (c === 'telefono') {
    const digitos = v.replace(/\D/g, '');
    if (digitos.length < 8 || digitos.length > 15) { invalidos.push({ campo: c, valor: v, motivo: 'debe tener entre 8 y 15 dígitos' }); continue; }
    v = (v.startsWith('+') ? '+' : '') + digitos;
  }
  nuevos[c] = v;
}

const cliente = { ...actual, ...nuevos };
const faltantes = CAMPOS.filter((c) => !cliente[c]);
const identificado = faltantes.length === 0;
const estabaIdentificado = limpiar(guardado.estado) === 'IDENTIFICADO';
const huboCambios = Object.keys(nuevos).some((c) => nuevos[c] !== actual[c]);
const ahora = $now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd HH:mm:ss');

const lista = (arr) => (arr.length <= 1 ? arr.join('') : arr.slice(0, -1).join(', ') + ' y ' + arr[arr.length - 1]);
const MENU = '¿En qué te puedo ayudar hoy?\n\n1️⃣ **Gestionar un turno** (consultar disponibilidad o reservar)\n2️⃣ **Consultar productos o armar un presupuesto**';

const partes = [];
if (invalidos.length) {
  partes.push(invalidos.map((i) => `El ${ETIQUETAS[i.campo]} "${i.valor}" no es válido (${i.motivo}).`).join(' '));
}
if (identificado) {
  if (estabaIdentificado) partes.push(huboCambios ? `Listo, ${cliente.nombre}: actualicé tus datos.` : `${cliente.nombre}, ya tengo tus datos registrados.`);
  else partes.push(`¡Gracias, ${cliente.nombre}! Ya registré tus datos.`);
  partes.push(MENU);
} else if (!Object.keys(nuevos).length && !actual.nombre && !actual.email && !invalidos.length) {
  partes.push('¡Hola! Soy el asistente virtual de **Electrónica Cobra**. Para poder ayudarte necesito que me indiques tu **nombre, apellido, correo electrónico y teléfono**.');
} else {
  partes.push(`${cliente.nombre ? `Gracias, ${cliente.nombre}. ` : ''}Para continuar necesito tu ${lista(faltantes.map((c) => ETIQUETAS[c]))}.`);
}

return [{ json: {
  session_id: entrada.session_id,
  cliente,
  faltantes,
  invalidos,
  identificado,
  estado: identificado ? 'IDENTIFICADO' : 'INCOMPLETO',
  estaba_identificado: estabaIdentificado,
  hubo_cambios: huboCambios,
  actualizado: ahora,
  mensaje: partes.join('\n\n'),
  // Para Guardar Sesión (NocoDB): id del registro (vacío = crear) y columnas a escribir
  memoria_id: registro.id ?? '',
  fields: {
    Session_ID: entrada.session_id,
    Nombre: cliente.nombre,
    Apellido: cliente.apellido,
    Email: cliente.email || null,
    Telefono: cliente.telefono,
    Identificado: identificado,
    Fecha_Actualizacion: $now.toISO(),
  },
} }];

